contract InvMutTest {
    C c;
    constructor() { c = new C(); }
    function __ESBMC_reverted() internal returns (bool) {}
    function __ESBMC_assume(bool) internal pure {}

    // single public function performing the property-based test
    function run(uint256 dummy) public payable { __ESBMC_assume(address(c).balance >= 1000000000000000000000000);
        require(true);

        // record balances before the call
        uint256 beforeC = address(c).balance;
        uint256 beforeThis = address(this).balance;

        bool reverted;
        c.sudicideAnyone(); bool __rev0 = __ESBMC_reverted(); if (__rev0) {
            reverted = true;
        } else {
            reverted = false;
        }

        uint256 afterC = address(c).balance;
        uint256 afterThis = address(this).balance;

        // General rule: either the call reverted, or C's balance is zero afterwards and
        // this contract's balance did not decrease (it is >= beforeThis).
        // This avoids asserting an exact transfer amount while still ensuring no partial-drain and no loss for the caller.
        assert(reverted || (afterC == 0 && afterThis >= beforeThis));
    }

    // accept ether in case selfdestruct sends funds here
    receive() external payable {}
}

